import heapq

def match(orders):
    trades = []
    book = {}  # id -> dict with side, price, qty, seq, active
    buy_heap = []  # (-price, seq, id)
    sell_heap = []  # (price, seq, id)
    seq_counter = 0

    def add_to_book(order_id, side, price, qty, seq):
        book[order_id] = {'side': side, 'price': price, 'qty': qty, 'seq': seq, 'active': True}
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, order_id))
        else:
            heapq.heappush(sell_heap, (price, seq, order_id))

    def top_valid_buy():
        while buy_heap:
            negprice, s, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
                continue
            return negprice, s, oid
        return None

    def top_valid_sell():
        while sell_heap:
            price, s, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
                continue
            return price, s, oid
        return None

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            _, oid = order
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'limit':
            _, oid, side, price, qty = order
        elif typ == 'ioc':
            _, oid, side, price, qty = order
        elif typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                top = top_valid_sell()
                if top is None:
                    break
                sprice, sseq, soid = top
                if typ != 'market' and price is not None:
                    if sprice > price:
                        break
                sinfo = book[soid]
                trade_qty = min(remaining, sinfo['qty'])
                trades.append([oid, soid, sprice, trade_qty])
                remaining -= trade_qty
                sinfo['qty'] -= trade_qty
                heapq.heappop(sell_heap)
                if sinfo['qty'] > 0:
                    heapq.heappush(sell_heap, (sinfo['price'], sinfo['seq'], soid))
                else:
                    sinfo['active'] = False
        else:  # sell
            while remaining > 0:
                top = top_valid_buy()
                if top is None:
                    break
                negprice, bseq, boid = top
                bprice = -negprice
                if typ != 'market' and price is not None:
                    if bprice < price:
                        break
                binfo = book[boid]
                trade_qty = min(remaining, binfo['qty'])
                trades.append([boid, oid, bprice, trade_qty])
                remaining -= trade_qty
                binfo['qty'] -= trade_qty
                heapq.heappop(buy_heap)
                if binfo['qty'] > 0:
                    heapq.heappush(buy_heap, (-binfo['price'], binfo['seq'], boid))
                else:
                    binfo['active'] = False

        if typ == 'limit' and remaining > 0:
            add_to_book(oid, side, price, remaining, seq)
        elif typ == 'limit' and remaining == 0:
            book[oid] = {'side': side, 'price': price, 'qty': 0, 'seq': seq, 'active': False}
        # ioc and market: discard remainder, no need to add to book
        # but still record in book as filled/inactive for cancel safety (optional)
        elif typ in ('ioc', 'market'):
            book[oid] = {'side': side, 'price': price if price is not None else 0, 'qty': 0, 'seq': seq, 'active': False}

    return trades

